fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cols: i32 = w / 8;
    let rows: i32 = h / 8;
    let mut by: i32 = 0;
    while by < rows {
        let mut bx: i32 = 0;
        while bx < cols {
            let v: i32 = ((bx ^ by) + t) % 256;
            let c: i32 = v * 65536 + (v / 2) * 256 + (255 - v);
            host::display::fill_rect(bx * 8, by * 8, 8, 8, c);
            bx = bx + 1;
        }
        by = by + 1;
    }
    host::display::present();
}
